sys_variable_value.value:
(function execute(inputs, outputs) {
// ... code ...
var utils = new global.PatientUtils(inputs.patientId);
var patientRecord = utils.PatientDetails();
if (!patientRecord) {
    outputs.error = 'Patient record not found';
    return;
}
outputs.first_name = patientRecord.getValue('u_first_name');
outputs.last_name = patientRecord.getValue('u_last_name');
outputs.gender = patientRecord.getDisplayValue('u_gender');
outputs.dob = patientRecord.getDisplayValue('u_dob');
outputs.contact_number = patientRecord.getDisplayValue('u_contact_number');
outputs.email = patientRecord.getValue('u_email');
outputs.address = patientRecord.getDisplayValue('u_address');
outputs.emergency_contact = patientRecord.getDisplayValue('u_emergency_contact');

// outputs.is_vip = utils.isPatientVip();


})(inputs, outputs);

